const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Utah geometry
  const utah = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'Utah'));
  const utahGeom = utah.geometry();

  // 2. Acquire soil moisture data - SMOS L3
  // Use SMOS (Soil Moisture and Ocean Salinity) dataset
  const smos = ee.ImageCollection('SMOS/Level3_Soil_Moisture')
    .filterBounds(utahGeom);

  // Filter for August 2020
  const aug2020 = smos
    .filter(ee.Filter.calendarRange(2020, 2020, 'year'))
    .filter(ee.Filter.calendarRange(8, 8, 'month'));

  const aug2020Size = await aug2020.size().getInfo();
  console.log(`August 2020 Images: ${aug2020Size}`);

  if (aug2020Size === 0) {
    console.log('No SMOS data for August 2020. Trying GLDAS...');
    // Fallback to GLDAS soil moisture
    const gldas2020 = ee.ImageCollection('NASA/GLDAS/V021/NOAH/G025/T3H')
      .filter(ee.Filter.calendarRange(2020, 2020, 'year'))
      .filter(ee.Filter.calendarRange(8, 8, 'month'))
      .filterBounds(utahGeom);

    const gldas2020Size = await gldas2020.size().getInfo();
    if (gldas2020Size === 0) {
      console.log('No soil moisture data found for August 2020.');
      console.log('C1');
      return;
    }
  }

  // 3. Historical August data (2015-2019 for long-term average)
  const historicalAugust = smos
    .filter(ee.Filter.calendarRange(2015, 2019, 'year'))
    .filter(ee.Filter.calendarRange(8, 8, 'month'));

  const historicalSize = await historicalAugust.size().getInfo();
  console.log(`Historical August Images (2015-2019): ${historicalSize}`);

  if (historicalSize === 0) {
    console.log('No historical soil moisture data. Trying GLDAS...');
    // Fallback to GLDAS for historical
    const gldas_hist = ee.ImageCollection('NASA/GLDAS/V021/NOAH/G025/T3H')
      .filter(ee.Filter.calendarRange(2015, 2019, 'year'))
      .filter(ee.Filter.calendarRange(8, 8, 'month'))
      .filterBounds(utahGeom);

    const gldas_hist_size = await gldas_hist.size().getInfo();
    if (gldas_hist_size === 0) {
      console.log('No historical data found.');
      console.log('C1');
      return;
    }
  }

  // 4. Calculate mean soil moisture for August 2020 using GLDAS (more reliable)
  const gldasCol = ee.ImageCollection('NASA/GLDAS/V021/NOAH/G025/T3H')
    .filterBounds(utahGeom);

  const aug2020GLDAS = gldasCol
    .filter(ee.Filter.calendarRange(2020, 2020, 'year'))
    .filter(ee.Filter.calendarRange(8, 8, 'month'));

  const historicalGLDAS = gldasCol
    .filter(ee.Filter.calendarRange(2015, 2019, 'year'))
    .filter(ee.Filter.calendarRange(8, 8, 'month'));

  // Mean for August 2020 (SoilMoist0_10cm_mean)
  const aug2020Mean = aug2020GLDAS.mean();
  const aug2020Val = await aug2020Mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: utahGeom,
    scale: 25000,
    maxPixels: 1e9
  }).getInfo();

  const soilMoist2020 = aug2020Val['SoilMoist_0_10cm_mean'];
  console.log(`August 2020 Mean Soil Moisture: ${soilMoist2020}`);

  // Count valid pixels for August 2020
  const countVal2020 = await aug2020Mean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: utahGeom,
    scale: 25000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount2020 = countVal2020['SoilMoist_0_10cm_mean'];
  console.log(`August 2020 Valid Pixels: ${pixelCount2020}`);

  if (!pixelCount2020 || pixelCount2020 === 0) {
    console.log('No valid pixels for August 2020 after processing.');
    console.log('C2');
    return;
  }

  // Mean for historical August (2015-2019)
  const historicalMean = historicalGLDAS.mean();
  const historicalVal = await historicalMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: utahGeom,
    scale: 25000,
    maxPixels: 1e9
  }).getInfo();

  const soilMoistHistorical = historicalVal['SoilMoist_0_10cm_mean'];
  console.log(`Historical August Mean Soil Moisture (2015-2019): ${soilMoistHistorical}`);

  // Count valid pixels for historical
  const countValHistorical = await historicalMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: utahGeom,
    scale: 25000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCountHistorical = countValHistorical['SoilMoist_0_10cm_mean'];
  console.log(`Historical Valid Pixels: ${pixelCountHistorical}`);

  if (!pixelCountHistorical || pixelCountHistorical === 0) {
    console.log('No valid pixels for historical data.');
    console.log('C2');
    return;
  }

  // 5. Validation & Comparison
  if (soilMoist2020 === null || soilMoistHistorical === null || 
      isNaN(soilMoist2020) || isNaN(soilMoistHistorical)) {
    console.log('Calculation failed: NaN or null values detected.');
    console.log('C3');
    return;
  }

  const difference = soilMoist2020 - soilMoistHistorical;
  const percentChange = ((difference / soilMoistHistorical) * 100).toFixed(2);

  console.log(`Difference: ${difference.toFixed(4)} (${percentChange}% change)`);

  // Determine if August 2020 shows decrease
  if (soilMoist2020 < soilMoistHistorical) {
    console.log('August 2020 soil moisture is LOWER than long-term average.');
    console.log('A');
  } else {
    console.log('August 2020 soil moisture is NOT lower than long-term average.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
